import type { Clock, TimeZone } from './ports';

function pad(value: number, width: number): string {
  return String(value).padStart(width, '0');
}

/** UTC string `YYYY-MM-DDTHH:mm:ss.sssZ` for an instant in epoch milliseconds. */
export function formatUtc(utcMillis: number): string {
  return new Date(utcMillis).toISOString();
}

type WallTime = { year: number; month: number; day: number; hour: number; minute: number };

/** Local wall time = UTC instant + zone offset at that instant, read with getUTC* (PLAT-WEB-020). */
function wallTime(utcMillis: number, offsetMinutes: number): WallTime {
  const d = new Date(utcMillis + offsetMinutes * 60000);
  return {
    year: d.getUTCFullYear(),
    month: d.getUTCMonth() + 1,
    day: d.getUTCDate(),
    hour: d.getUTCHours(),
    minute: d.getUTCMinutes(),
  };
}

function dateText(w: WallTime): string {
  return `${pad(w.year, 4)}-${pad(w.month, 2)}-${pad(w.day, 2)}`;
}

/**
 * `HH:mm`, or `YYYY-MM-DD HH:mm` when the message's local date differs from the viewer's current local date.
 * Zone and "now" are read at the moment of the call, never cached (CORE-TIME-002). Seconds are truncated.
 */
export function formatMessageTime(acceptedAt: string, clock: Clock, zone: TimeZone): string | null {
  const t = Date.parse(acceptedAt);
  if (Number.isNaN(t)) return null;
  const now = clock.now();
  const local = wallTime(t, zone.offsetMinutesAt(t));
  const today = wallTime(now, zone.offsetMinutesAt(now));
  const hhmm = `${pad(local.hour, 2)}:${pad(local.minute, 2)}`;
  return dateText(local) === dateText(today) ? hhmm : `${dateText(local)} ${hhmm}`;
}

/** Time text of a stored message: none without seq (CORE-VISIBLE-009). */
export function messageTimeText(
  message: { seq: number | null; accepted_at: string | null },
  clock: Clock,
  zone: TimeZone,
): string | null {
  if (message.seq === null || message.accepted_at === null) return null;
  return formatMessageTime(message.accepted_at, clock, zone);
}
